<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityUidAttributeHolder;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityUserAttributeHolder;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityLoginProviderAttributeHolder;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentitySubjectAttributeHolder;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityCreatedAtAttributeHolder;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class UserFederatedIdentityAttributes
{
    use UserFederatedIdentityUidAttributeHolder;
    use UserFederatedIdentityUserAttributeHolder;
    use UserFederatedIdentityLoginProviderAttributeHolder;
    use UserFederatedIdentitySubjectAttributeHolder;
    use UserFederatedIdentityCreatedAtAttributeHolder;
    use UserFederatedIdentityVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'user' => 'unsetUser',
      'loginProvider' => 'unsetLoginProvider',
      'subject' => 'unsetSubject',
      'createdAt' => 'unsetCreatedAt',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): UserFederatedIdentity
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $user = $this->userTryBuildInitial($errors);
        $loginProvider = $this->loginProviderTryBuildInitial($errors);
        $subject = $this->subjectTryBuildInitial($errors);
        $createdAt = $this->createdAtTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($user !== null);
        \assert($loginProvider !== null);
        \assert($subject !== null);
        return new UserFederatedIdentity(
            uid: $uid,
            user: $user,
            loginProvider: $loginProvider,
            subject: $subject,
            createdAt: $createdAt,
            version: $version,
        );
    }
    public function withAssertedRules(): UserFederatedIdentityAttributes
    {
        $value = new UserFederatedIdentityAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedUserRules($value, $errorsList);
        $this->withAssertedLoginProviderRules($value, $errorsList);
        $this->withAssertedSubjectRules($value, $errorsList);
        $this->withAssertedCreatedAtRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): UserFederatedIdentityAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultUser();
        $this->withDefaultLoginProvider();
        $this->withDefaultSubject();
        $this->withDefaultCreatedAt();
        $this->withDefaultVersion();
        return $this;
    }
}
